  /// pending, synced, error, local_only
  final String syncStatus;

  /// cloud_provider, onedrive_local, health_connect, etc.
  final String? sourceProvider;

  /// The unique ID from the source provider (e.g., file path, API ID).
  final String? sourceIdentifier;

  /// hash of the content for duplicate detection.
  final String? contentHash;
  final String? deviceId;

  /// Source memory node (MemoryID).
  final String sourceId;

  /// Target memory node (MemoryID).
  final String targetId;

  /// parent, child, influences, caused_by, duplicate, derived_from, references.
  final String type;

  /// 0.0 to 1.0 link strength.
  final double strength;

  /// JSON metadata for the edge.
  final String metadata;
  const MemoryRelationData({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    required this.version,
    required this.isDeleted,
    this.deletedAt,
