class SyncTask extends DataClass implements Insertable<SyncTask> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final int version;
  final bool isDeleted;
  final DateTime? deletedAt;

  /// pending, synced, error, local_only
  final String syncStatus;

  /// cloud_provider, onedrive_local, health_connect, etc.
  final String? sourceProvider;

  /// The unique ID from the source provider (e.g., file path, API ID).
  final String? sourceIdentifier;

  /// hash of the content for duplicate detection.
  final String? contentHash;
  final String? deviceId;

  /// Provider responsible for this task.
  final String providerId;

  /// Type of task (e.g., 'parse_email', 'generate_summary').
  final String taskType;

  /// JSON payload containing required data to execute the task.
  final String payload;

