class ParserMetadata extends DataClass implements Insertable<ParserMetadata> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final int version;
  final bool isDeleted;
  final DateTime? deletedAt;

  /// pending, synced, error, local_only
  final String syncStatus;

  /// cloud_provider, onedrive_local, health_connect, etc.
  final String? sourceProvider;

  /// The unique ID from the source provider (e.g., file path, API ID).
  final String? sourceIdentifier;

  /// hash of the content for duplicate detection.
  final String? contentHash;
  final String? deviceId;

  /// Unique name (e.g., 'financial_statement_v4').
  final String parserId;

  /// Semantic version (e.g. '1.0.2').
  final String parserVersion;

  /// Target entity type (e.g., 'transaction', 'flight').
  final String targetType;

  /// Total items processed.
  final int totalProcessed;

  /// Items successfully verified by user.
  final int verificationCount;

  /// Performance Metrics (M3 Requirement)
  final double? accuracy;
  final int falsePositives;
  final int falseNegatives;
  final double? averageConfidence;

  /// Last used timestamp.
  final DateTime lastUsed;
  const ParserMetadata({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    required this.version,
    required this.isDeleted,
    this.deletedAt,
    required this.syncStatus,
    this.sourceProvider,
    this.sourceIdentifier,
    this.contentHash,
    this.deviceId,
    required this.parserId,
    required this.parserVersion,
    required this.targetType,
    required this.totalProcessed,
    required this.verificationCount,
    this.accuracy,
    required this.falsePositives,
    required this.falseNegatives,
    this.averageConfidence,
    required this.lastUsed,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['version'] = Variable<int>(version);
    map['is_deleted'] = Variable<bool>(isDeleted);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['sync_status'] = Variable<String>(syncStatus);
    if (!nullToAbsent || sourceProvider != null) {
      map['source_provider'] = Variable<String>(sourceProvider);
    }
    if (!nullToAbsent || sourceIdentifier != null) {
      map['source_identifier'] = Variable<String>(sourceIdentifier);
    }
    if (!nullToAbsent || contentHash != null) {
      map['content_hash'] = Variable<String>(contentHash);
    }
    if (!nullToAbsent || deviceId != null) {
      map['device_id'] = Variable<String>(deviceId);
    }
    map['parser_id'] = Variable<String>(parserId);
    map['parser_version'] = Variable<String>(parserVersion);
    map['target_type'] = Variable<String>(targetType);
    map['total_processed'] = Variable<int>(totalProcessed);
    map['verification_count'] = Variable<int>(verificationCount);
    if (!nullToAbsent || accuracy != null) {
      map['accuracy'] = Variable<double>(accuracy);
    }
    map['false_positives'] = Variable<int>(falsePositives);
    map['false_negatives'] = Variable<int>(falseNegatives);
    if (!nullToAbsent || averageConfidence != null) {
      map['average_confidence'] = Variable<double>(averageConfidence);
    }
    map['last_used'] = Variable<DateTime>(lastUsed);
    return map;
  }

  ParserRegistryTableCompanion toCompanion(bool nullToAbsent) {
    return ParserRegistryTableCompanion(
      id: Value(id),
