class ExtractedEntity extends DataClass implements Insertable<ExtractedEntity> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;

  /// Incremental entity version.
  final int version;
  final bool isDeleted;
  final DateTime? deletedAt;

  /// pending, synced, error, local_only
  final String syncStatus;

  /// cloud_provider, onedrive_local, health_connect, etc.
  final String? sourceProvider;

  /// The unique ID from the source provider (e.g., file path, API ID).
  final String? sourceIdentifier;

  /// hash of the content for duplicate detection.
  final String? contentHash;
  final String? deviceId;

  /// e.g. transaction, booking, order, bill.
  final String entityType;

  /// e.g. upi, flight, amazon_order.
  final String entitySubtype;

  /// Reference to normalized identity (e.g. AMAZON).
  final String? canonicalId;

  /// Human-readable title.
  final String title;

  /// Short summary of the entity.
  final String? summary;

  /// Logical timestamp of the event.
  final DateTime eventTimestamp;

  /// When the source was received.
  final DateTime receivedTimestamp;

  /// Name of the parser used.
  final String parserName;

  /// Version of the parser used.
  final String parserVersion;

  /// 0.0 to 1.0.
  final double confidenceScore;

  /// Reasoning for the score.
  final String? confidenceReason;

  /// unverified, likely, verified, user_confirmed, user_corrected, system_revalidated.
  final String verificationState;

  /// Whether the user has manually corrected this.
  final bool userCorrected;

  /// Batch ID for the extraction run.
  final String? syncBatchId;

  /// Reference to the evidence.
  final String? evidenceId;

  /// When the extraction was performed.
  final DateTime extractionTimestamp;
