class TrustMetricData extends DataClass implements Insertable<TrustMetricData> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final int version;
  final bool isDeleted;
  final DateTime? deletedAt;

  /// pending, synced, error, local_only
  final String syncStatus;

  /// cloud_provider, onedrive_local, health_connect, etc.
  final String? sourceProvider;

  /// The unique ID from the source provider (e.g., file path, API ID).
  final String? sourceIdentifier;

  /// hash of the content for duplicate detection.
  final String? contentHash;
  final String? deviceId;

  /// Reference to the node or edge being measured
  final String targetId;

  /// 0.0 (Unreliable) to 1.0 (Canonical Truth)
  final double score;

  /// Probability that the extraction/linkage is correct
  final double confidence;

  /// Version of the Trust Engine that calculated this score
  final String algorithmVersion;

  /// Reasoning trace for the trust score
  final String? calculationReason;
  final DateTime lastCalculatedAt;
